# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HARFLERİN MAHREÇ BÖLGELERİ (5 TEMEL ÇIKIŞ BÖLGESİ)</text>\n  <rect x="20" y="42" width="210" height="200" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. BOĞAZ (HALK) - 6 HARF</text>\n  <text x="32" y="88" font-size="11" fill="#1e3a8a">• Boğazın Göğse Bitişik Yeri:</text>\n  <text x="42" y="105" font-size="12" font-weight="bold" fill="#1d4ed8">ء (Hemze)  —  هـ (Hâ)</text>\n  <text x="32" y="128" font-size="11" fill="#1e3a8a">• Boğazın Ortası:</text>\n  <text x="42" y="145" font-size="12" font-weight="bold" fill="#1d4ed8">ع (Ayın)  —  ح (Hâ)</text>\n  <text x="32" y="168" font-size="11" fill="#1e3a8a">• Boğazın Ağıza Yakın Üst Kısmı:</text>\n  <text x="42" y="185" font-size="12" font-weight="bold" fill="#1d4ed8">غ (Gayın)  —  خ (Hı)</text>\n  <text x="32" y="218" font-size="10.5" font-weight="bold" fill="#2563eb">Bunlara İzhâr (Boğaz) harfleri denir.</text>\n  <rect x="245" y="42" width="210" height="200" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">2. DİL (LİSÂN) VE 3. DUDAK</text>\n  <text x="257" y="88" font-size="11" font-weight="bold" fill="#14532d">• Dil (Lisân) - 18 Harf (En geniş):</text>\n  <text x="262" y="106" font-size="10.5" fill="#166534">- Dil kökü: ق ، ك  |  Dil ortası: ج ، ش ، ي</text>\n  <text x="262" y="122" font-size="10.5" fill="#166534">- Dil yan kenarı: ض  |  Dil ucu: ل ، ن ، ر</text>\n  <text x="262" y="138" font-size="10.5" fill="#166534">- Dil ucu + üst ön dişler: ط ، د ، ت ve ظ ، ذ ، ث</text>\n  <text x="262" y="154" font-size="10.5" fill="#166534">- Dil ucu + alt-üst ön dişler: ص ، ز ، س</text>\n  <text x="257" y="178" font-size="11" font-weight="bold" fill="#14532d">• Dudak (Şefetân) - 4 Harf:</text>\n  <text x="262" y="196" font-size="11.5" font-weight="bold" fill="#15803d">ف (Üst diş + alt dudak) | ب ، م ، و (İki dudak)</text>\n  <rect x="470" y="42" width="210" height="200" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">4. CEVF VE 5. HAYŞÛM</text>\n  <text x="482" y="92" font-size="11" font-weight="bold" fill="#78350f">• Cevf (Ağız-Boğaz Boşluğu):</text>\n  <text x="488" y="110" font-size="11" fill="#92400e">Uzatma (Med) harfleri olan</text>\n  <text x="488" y="128" font-size="12" font-weight="bold" fill="#b45309">ا (Elif) — و (Vâv) — ي (Yâ)</text>\n  <text x="488" y="144" font-size="10.5" fill="#92400e">boşluktan sesin uzamasıyla çıkar.</text>\n  <text x="482" y="172" font-size="11" font-weight="bold" fill="#78350f">• Hayşûm (Geniz / Burun Boşluğu):</text>\n  <text x="488" y="190" font-size="11" fill="#92400e">م (Mîm) ve ن (Nûn) harflerinin</text>\n  <text x="488" y="206" font-size="11" font-weight="bold" fill="#b45309">şeddeli/idgamlı/ihfâlı okunuşundaki</text>\n  <text x="488" y="222" font-size="11" font-weight="bold" fill="#b45309">GUNNE (geniz sesi) buradan çıkar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HARFLERİN SIFATLARI VE MEDD-İ TABİÎ (ASLİ MED)</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">HARFLERİN BAŞLICA SIFATLARI</text>\n  <text x="38" y="92" font-size="11.5" fill="#581c87">• Peltek Harfler (3): ث (Sâ) ، ذ (Zel) ، ظ (Zı)</text>\n  <text x="38" y="114" font-size="11.5" fill="#581c87">• Kalın (İsti\'lâ) Harfler (7): خ ص ض غ ط ق ظ</text>\n  <text x="48" y="130" font-size="10.5" fill="#7e22ce">(Kodlama: خُصَّ ضَغْطٍ قِظْ — Hussa Dağtın Kız)</text>\n  <text x="38" y="152" font-size="11.5" fill="#581c87">• Kalkale Harfleri (5): ق ط ب ج د (قُطْبُ جَدٍ)</text>\n  <text x="48" y="168" font-size="10.5" fill="#7e22ce">(Cezimli olduğunda mahreçte sarsılarak/vurularak okunur)</text>\n  <text x="38" y="190" font-size="11.5" fill="#581c87">• Safîr (Keskin/Islık Sesi) Harfler (3): ص ، ز ، س</text>\n  <text x="38" y="212" font-size="11.5" fill="#581c87">• Şemsî (14) ve Kamerî (14) Harfler: ال takısının okunuşu.</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">MED KAVRAMI VE MEDD-İ TABİÎ (ASLİ MED)</text>\n  <text x="370" y="90" font-size="11.5" font-weight="bold" fill="#7c2d12">• Med Harfleri (حُرُوفُ الْمَدِّ): ا ، و ، ي</text>\n  <text x="378" y="108" font-size="11" fill="#9a3412">- Üstünlü harften sonra harekesiz ا gelirse (قَالَ)</text>\n  <text x="378" y="124" font-size="11" fill="#9a3412">- Ötreli harften sonra cezimli و gelirse (يَقُولُ)</text>\n  <text x="378" y="140" font-size="11" fill="#9a3412">- Esreli harften sonra cezimli ي gelirse (قِيلَ)</text>\n  <rect x="370" y="152" width="290" height="76" rx="6" fill="#ffedd5" stroke="#fb923c"/>\n  <text x="515" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#c2410c">Medd-i Tabiî (Doğal Uzatma):</text>\n  <text x="515" y="190" text-anchor="middle" font-size="11" fill="#7c2d12">Med harfinden sonra sebeb-i med (hemze veya sükûn) YOKSA</text>\n  <text x="515" y="208" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">1 Elif miktarı (iki hareke süresi) uzatılarak okunur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">FER\'Î MED ÇEŞİTLERİ (SEBEB-İ MED: HEMZE VE SÜKÛN)</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#155e75">HEMZE SEBEBİYLE OLUŞAN MEDLER</text>\n  <rect x="38" y="78" width="288" height="72" rx="6" fill="#ffffff" stroke="#67e8f9"/>\n  <text x="48" y="98" font-size="12" font-weight="bold" fill="#0e7490">1. Medd-i Muttasıl (Bitişik Med):</text>\n  <text x="48" y="116" font-size="11" fill="#164e63">Med harfi ile hemze (ء) AYNI kelimede yan yana gelir.</text>\n  <text x="48" y="134" font-size="11" font-weight="bold" fill="#155e75">• Örnek: جَآءَ ، سُوءَ ، شَآءَ | Hükmü: VACİP (4 Elif)</text>\n  <rect x="38" y="158" width="288" height="72" rx="6" fill="#ffffff" stroke="#67e8f9"/>\n  <text x="48" y="178" font-size="12" font-weight="bold" fill="#0e7490">2. Medd-i Munfasıl (Ayrı Med):</text>\n  <text x="48" y="196" font-size="11" fill="#164e63">Med harfi ilk kelimenin sonunda, hemze ikinci kelimenin başında.</text>\n  <text x="48" y="214" font-size="11" font-weight="bold" fill="#155e75">• Örnek: يَا أَيُّهَا ، إِنَّا أَعْطَيْنَاكَ | Hükmü: CAİZ (1-4 Elif)</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#9f1239">SÜKÛN SEBEBİYLE OLUŞAN MEDLER</text>\n  <text x="370" y="92" font-size="11.5" font-weight="bold" fill="#881337">3. Medd-i Lâzım (Sükûn-u Lâzım / Kalıcı Sükûn):</text>\n  <text x="378" y="110" font-size="11" fill="#9f1239">Med harfinden sonra durulsa da geçilse de sabit olan</text>\n  <text x="378" y="126" font-size="11" fill="#9f1239">cezim/şedde gelir (الضَّآلِّينَ ، الم). Hükmü: LÂZIM (4 Elif).</text>\n  <text x="370" y="152" font-size="11.5" font-weight="bold" fill="#881337">4. Medd-i Ârız (Sükûn-u Ârız / Geçici Sükûn):</text>\n  <text x="378" y="170" font-size="11" fill="#9f1239">Med harfinden sonraki son harfte vakıf (durak) sebebiyle</text>\n  <text x="378" y="186" font-size="11" fill="#9f1239">oluşan geçici sükûndur (الْعَالَمِينَ ← الْعَالَمِينْ). Hükmü: CAİZ.</text>\n  <text x="370" y="210" font-size="11.5" font-weight="bold" fill="#881337">5. Medd-i Lîn: Üstün + Cezimli و / ي + Sükûn (خَوْفْ ، قُرَيْشْ).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
